#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

void launch_indexer_cuda(const at::Tensor& q_input,
                         const at::Tensor& weight,
                         double weight_scale,
                         const at::Tensor& freqs,
                         const at::Tensor& positions,
                         at::Tensor& q_fp8,
                         at::Tensor& weights_out,
                         cudaStream_t stream);

std::vector<at::Tensor> indexer(at::Tensor q_input, at::Tensor weight, double weight_scale,
                                at::Tensor freqs, at::Tensor positions) {
  TORCH_CHECK(q_input.is_cuda(), "q_input must be CUDA");
  TORCH_CHECK(weight.is_cuda() && freqs.is_cuda() && positions.is_cuda(), "all tensors must be CUDA");
  TORCH_CHECK(q_input.dim() == 3 && q_input.size(2) == 128, "q_input must have shape [B,H,128]");
  TORCH_CHECK(weight.dim() == 2 && weight.size(0) == q_input.size(0) && weight.size(1) == q_input.size(1),
              "weight must have shape [B,H]");
  TORCH_CHECK(freqs.dim() == 2 && freqs.size(1) == 64, "freqs must have shape [max_seq_len,64]");
  TORCH_CHECK(positions.dim() == 1 && positions.size(0) == q_input.size(0), "positions must have shape [B]");
  TORCH_CHECK(q_input.scalar_type() == at::kHalf || q_input.scalar_type() == at::kBFloat16,
              "q_input must be float16 or bfloat16");
  TORCH_CHECK(weight.scalar_type() == q_input.scalar_type(), "weight dtype must match q_input dtype");
  TORCH_CHECK(freqs.scalar_type() == at::kFloat, "freqs must be float32 real/imag table");
  TORCH_CHECK(positions.scalar_type() == at::kInt || positions.scalar_type() == at::kLong,
              "positions must be int32 or int64");
  TORCH_CHECK(q_input.is_contiguous(), "q_input must be contiguous");
  TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
  TORCH_CHECK(freqs.is_contiguous(), "freqs must be contiguous");
  TORCH_CHECK(positions.is_contiguous(), "positions must be contiguous");

  const c10::cuda::CUDAGuard device_guard(q_input.device());
  auto q_fp8 = at::empty(q_input.sizes(), q_input.options().dtype(at::ScalarType::Float8_e4m3fn));
  auto weights_out = at::empty({q_input.size(0), q_input.size(1), 1}, q_input.options().dtype(at::kFloat));
  if (q_input.numel() == 0) {
    return {q_fp8, weights_out};
  }
  launch_indexer_cuda(q_input, weight, weight_scale, freqs, positions, q_fp8, weights_out,
                      at::cuda::getCurrentCUDAStream());
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return {q_fp8, weights_out};
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("indexer", &indexer, "DSV4 indexer RoPE+Hadamard+FP8 quant (CUDA)");
}
