cat > dsv4_indexer/cuda_ext/indexer_kernels.cu <<'EOF'
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp8.h>
#include <cstdint>
#include <cmath>

namespace {

constexpr int kHeadDim = 128;
constexpr int kRopeDim = 64;
constexpr int kWarpThreads = 32;
constexpr int kVecSize = 4;
constexpr int kRopeLanes = kRopeDim / kVecSize;  // 16
constexpr int kWarpsPerBlock = 4;
constexpr int kBlockThreads = kWarpThreads * kWarpsPerBlock;
constexpr float kFP8E4M3Max = 448.0f;

__device__ __forceinline__ float fp8_clip(float x) {
  return fminf(fmaxf(x, -kFP8E4M3Max), kFP8E4M3Max);
}

__device__ __forceinline__ uint16_t pack_fp8(float x, float y) {
  const float2 v = make_float2(fp8_clip(x), fp8_clip(y));
  const __nv_fp8x2_e4m3 r(v);
  return r.__x;
}

__device__ __forceinline__ float warp_reduce_max(float v) {
#pragma unroll
  for (int mask = 16; mask > 0; mask >>= 1) {
    v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, mask, kWarpThreads));
  }
  return v;
}

template <typename scalar_t, typename pos_t>
__global__ __launch_bounds__(kBlockThreads, 16)
void indexer_kernel(const scalar_t* __restrict__ q_input,
                    const scalar_t* __restrict__ weight,
                    float weight_scale,
                    const float* __restrict__ freqs,
                    const pos_t* __restrict__ positions,
                    uint8_t* __restrict__ q_fp8,
                    float* __restrict__ weights_out,
                    int total_rows,
                    int num_heads) {
  const int warp_id = threadIdx.x >> 5;
  const int lane = threadIdx.x & 31;
  const int row = blockIdx.x * kWarpsPerBlock + warp_id;
  if (row >= total_rows) return;

  const int batch = row / num_heads;
  const int pos = static_cast<int>(positions[batch]);
  const scalar_t* in = q_input + row * kHeadDim;
  const float* freq_base = freqs + pos * kRopeDim;

  float data0 = static_cast<float>(in[lane * 4 + 0]);
  float data1 = static_cast<float>(in[lane * 4 + 1]);
  float data2 = static_cast<float>(in[lane * 4 + 2]);
  float data3 = static_cast<float>(in[lane * 4 + 3]);

  // RoPE over the final 64 dimensions: lanes 16..31 own two complex pairs each.
  if (lane >= (kWarpThreads - kRopeLanes)) {
    const int rope_lane = lane - (kWarpThreads - kRopeLanes);
    const float fxr = freq_base[rope_lane * 4 + 0];
    const float fxi = freq_base[rope_lane * 4 + 1];
    const float fyr = freq_base[rope_lane * 4 + 2];
    const float fyi = freq_base[rope_lane * 4 + 3];
    const float x_real = data0, x_imag = data1;
    const float y_real = data2, y_imag = data3;
    data0 = x_real * fxr - x_imag * fxi;
    data1 = x_real * fxi + x_imag * fxr;
    data2 = y_real * fyr - y_imag * fyi;
    data3 = y_real * fyi + y_imag * fyr;
  }

  // 128-point lane-major Hadamard: two local butterflies, five cross-lane stages.
  {
    const float a0 = data0, a1 = data1, a2 = data2, a3 = data3;
    data0 = a0 + a1;
    data1 = a0 - a1;
    data2 = a2 + a3;
    data3 = a2 - a3;
  }
  {
    const float a0 = data0, a1 = data1, a2 = data2, a3 = data3;
    data0 = a0 + a2;
    data1 = a1 + a3;
    data2 = a0 - a2;
    data3 = a1 - a3;
  }
#pragma unroll
  for (int mask = 1; mask < kWarpThreads; mask <<= 1) {
    float o0 = __shfl_xor_sync(0xffffffffu, data0, mask, kWarpThreads);
    float o1 = __shfl_xor_sync(0xffffffffu, data1, mask, kWarpThreads);
    float o2 = __shfl_xor_sync(0xffffffffu, data2, mask, kWarpThreads);
    float o3 = __shfl_xor_sync(0xffffffffu, data3, mask, kWarpThreads);
    if (lane & mask) {
      data0 = o0 - data0;
      data1 = o1 - data1;
      data2 = o2 - data2;
      data3 = o3 - data3;
    } else {
      data0 = data0 + o0;
      data1 = data1 + o1;
      data2 = data2 + o2;
      data3 = data3 + o3;
    }
  }
  constexpr float kHadamardScale = 0.08838834764831845f;  // rsqrt(128)
  data0 *= kHadamardScale;
  data1 *= kHadamardScale;
  data2 *= kHadamardScale;
  data3 *= kHadamardScale;

  float local_max = fmaxf(fmaxf(fabsf(data0), fabsf(data1)), fmaxf(fabsf(data2), fabsf(data3)));
  const float abs_max = warp_reduce_max(local_max);
  const float scale = fmaxf(1.0e-4f, abs_max) / kFP8E4M3Max;
  const float inv_scale = 1.0f / scale;

  uint16_t r0 = pack_fp8(data0 * inv_scale, data1 * inv_scale);
  uint16_t r1 = pack_fp8(data2 * inv_scale, data3 * inv_scale);
  uint32_t packed = static_cast<uint32_t>(r0) | (static_cast<uint32_t>(r1) << 16);
  reinterpret_cast<uint32_t*>(q_fp8 + row * kHeadDim)[lane] = packed;

  // One scalar per row. Broadcast is not necessary for correctness; doing the
  // store from a single lane avoids the benign same-address race in the JIT path.
  if (lane == 0) {
    const float w = static_cast<float>(weight[row]);
    weights_out[row] = w * weight_scale * scale;
  }
}

} // namespace

void launch_indexer_cuda(const at::Tensor& q_input,
                         const at::Tensor& weight,
                         double weight_scale,
                         const at::Tensor& freqs,
                         const at::Tensor& positions,
                         at::Tensor& q_fp8,
                         at::Tensor& weights_out,
                         cudaStream_t stream) {
  const int B = static_cast<int>(q_input.size(0));
  const int H = static_cast<int>(q_input.size(1));
  const int total_rows = B * H;
  const dim3 block(kBlockThreads);
  const dim3 grid((total_rows + kWarpsPerBlock - 1) / kWarpsPerBlock);

  if (q_input.scalar_type() == at::kHalf) {
    const auto* q = reinterpret_cast<const at::Half*>(q_input.data_ptr<at::Half>());
    const auto* w = reinterpret_cast<const at::Half*>(weight.data_ptr<at::Half>());
    if (positions.scalar_type() == at::kInt) {
      indexer_kernel<at::Half, int32_t><<<grid, block, 0, stream>>>(q, w, static_cast<float>(weight_scale),
          freqs.data_ptr<float>(), positions.data_ptr<int32_t>(), reinterpret_cast<uint8_t*>(q_fp8.data_ptr()),
          weights_out.data_ptr<float>(), total_rows, H);
    } else {
      indexer_kernel<at::Half, int64_t><<<grid, block, 0, stream>>>(q, w, static_cast<float>(weight_scale),
          freqs.data_ptr<float>(), positions.data_ptr<int64_t>(), reinterpret_cast<uint8_t*>(q_fp8.data_ptr()),
          weights_out.data_ptr<float>(), total_rows, H);
    }
  } else {
    const auto* q = reinterpret_cast<const at::BFloat16*>(q_input.data_ptr<at::BFloat16>());
    const auto* w = reinterpret_cast<const at::BFloat16*>(weight.data_ptr<at::BFloat16>());
    if (positions.scalar_type() == at::kInt) {
      indexer_kernel<at::BFloat16, int32_t><<<grid, block, 0, stream>>>(q, w, static_cast<float>(weight_scale),
          freqs.data_ptr<float>(), positions.data_ptr<int32_t>(), reinterpret_cast<uint8_t*>(q_fp8.data_ptr()),
          weights_out.data_ptr<float>(), total_rows, H);
    } else {
      indexer_kernel<at::BFloat16, int64_t><<<grid, block, 0, stream>>>(q, w, static_cast<float>(weight_scale),
          freqs.data_ptr<float>(), positions.data_ptr<int64_t>(), reinterpret_cast<uint8_t*>(q_fp8.data_ptr()),
          weights_out.data_ptr<float>(), total_rows, H);
    }
  }
}
