    v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, mask, kWarpThreads));
  }
  return v;
}

template <typename T>
__device__ __forceinline__ float load_as_float(const T* p, int idx);

template <>
__device__ __forceinline__ float load_as_float<__half>(const __half* p, int idx) {
  return __half2float(p[idx]);
}

template <>
__device__ __forceinline__ float load_as_float<__nv_bfloat16>(const __nv_bfloat16* p, int idx) {
  return __bfloat162float(p[idx]);
}

template <typename scalar_t, typename pos_t>
__global__ __launch_bounds__(kBlockThreads, 16)
void indexer_kernel(const scalar_t* __restrict__ q_input,
                    const scalar_t* __restrict__ weight,
                    float weight_scale,
                    const float* __restrict__ freqs,
                    const pos_t* __restrict__ positions,
                    uint8_t* __restrict__ q_fp8,
                    float* __restrict__ weights_out,
                    int total_rows,
                    int num_heads) {
  const int warp_id = threadIdx.x >> 5;
  const int lane = threadIdx.x & 31;
  const int row = blockIdx.x * kWarpsPerBlock + warp_id;
  if (row >= total_rows) return;

  const int batch = row / num_heads;
  const int pos = static_cast<int>(positions[batch]);
  const scalar_t* in = q_input + row * kHeadDim;
  const float* freq_base = freqs + pos * kRopeDim;

  float data0 = load_as_float(in, lane * 4 + 0);
  float data1 = load_as_float(in, lane * 4 + 1);
  float data2 = load_as_float(in, lane * 4 + 2);
  float data3 = load_as_float(in, lane * 4 + 3);

  if (lane >= (kWarpThreads - kRopeLanes)) {
    const int rope_lane = lane - (kWarpThreads - kRopeLanes);
    const float fxr = freq_base[rope_lane * 4 + 0];
    const float fxi = freq_base[rope_lane * 4 + 1];
    const float fyr = freq_base[rope_lane * 4 + 2];
    const float fyi = freq_base[rope_lane * 4 + 3];
    const float x_real = data0, x_imag = data1;
    const float y_real = data2, y_imag = data3;
    data0 = x_real * fxr - x_imag * fxi;
    data1 = x_real * fxi + x_imag * fxr;
    data2 = y_real * fyr - y_imag * fyi;
    data3 = y_real * fyi + y_imag * fyr;
  }

  {
    const float a0 = data0, a1 = data1, a2 = data2, a3 = data3;
    data0 = a0 + a1;
    data1 = a0 - a1;
    data2 = a2 + a3;
    data3 = a2 - a3;
  }
  {
    const float a0 = data0, a1 = data1, a2 = data2, a3 = data3;
    data0 = a0 + a2;
    data1 = a1 + a3;
    data2 = a0 - a2;
    data3 = a1 - a3;
  }
#pragma unroll
  for (int mask = 1; mask < kWarpThreads; mask <<= 1) {
    const float o0 = __shfl_xor_sync(0xffffffffu, data0, mask, kWarpThreads);
    const float o1 = __shfl_xor_sync(0xffffffffu, data1, mask, kWarpThreads);
    const float o2 = __shfl_xor_sync(0xffffffffu, data2, mask, kWarpThreads);
    const float o3 = __shfl_xor_sync(0xffffffffu, data3, mask, kWarpThreads);
    if (lane & mask) {
      data0 = o0 - data0; data1 = o1 - data1; data2 = o2 - data2; data3 = o3 - data3;
    } else {
      data0 = data0 + o0; data1 = data1 + o1; data2 = data2 + o2; data3 = data3 + o3;
    }
  }
  const float kHadamardScale = rsqrtf(static_cast<float>(kHeadDim));
  data0 *= kHadamardScale; data1 *= kHadamardScale; data2 *= kHadamardScale; data3 *= kHadamardScale;

  float local_max = fmaxf(fmaxf(fabsf(data0), fabsf(data1)), fmaxf(fabsf(data2), fabsf(data3)));
  const float abs_max = warp_reduce_max(local_max);
  const float scale = fmaxf(1.0e-4f, abs_max) / kFP8E4M3Max;
  const float inv_scale = 1.0f / scale;

  const uint16_t r0 = pack_fp8(data0 * inv_scale, data1 * inv_scale);
  const uint16_t r1 = pack_fp8(data2 * inv_scale, data3 * inv_scale);
  reinterpret_cast<uint32_t*>(q_fp8 + row * kHeadDim)[lane] = static_cast<uint32_t>(r0) | (static_cast<uint32_t>(r1) << 16);

  if (lane == 0) {
    weights_out[row] = load_as_float(weight, row) * weight_scale * scale;
  }
}

template <typename scalar_t, typename pos_t>
void launch_typed(const void* q_input, const void* weight, float weight_scale, const float* freqs,
                  const void* positions, void* q_fp8, float* weights_out, int B, int H, cudaStream_t stream) {
  const int total_rows = B * H;
  const dim3 block(kBlockThreads);
  const dim3 grid((total_rows + kWarpsPerBlock - 1) / kWarpsPerBlock);
  indexer_kernel<scalar_t, pos_t><<<grid, block, 0, stream>>>(
      static_cast<const scalar_t*>(q_input), static_cast<const scalar_t*>(weight), weight_scale,
      freqs, static_cast<const pos_t*>(positions), static_cast<uint8_t*>(q_fp8), weights_out, total_rows, H);
}

} // namespace

extern "C" void launch_indexer_cuda_raw(const void* q_input,
                             const void* weight,
                             int dtype_code,
                             double weight_scale,
                             const float* freqs,
                             const void* positions,
                             bool positions_int64,
                             void* q_fp8,
                             float* weights_out,
                             int batch_size,
                             int num_heads,
                             cudaStream_t stream) {
  if (dtype_code == 0) {
    if (positions_int64) launch_typed<__half, int64_t>(q_input, weight, static_cast<float>(weight_scale), freqs, positions, q_fp8, weights_out, batch_size, num_heads, stream);
    else launch_typed<__half, int32_t>(q_input, weight, static_cast<float>(weight_scale), freqs, positions, q_fp8, weights_out, batch_size, num_heads, stream);
  } else {
    if (positions_int64) launch_typed<__nv_bfloat16, int64_t>(q_input, weight, static_cast<float>(weight_scale), freqs, positions, q_fp8, weights_out, batch_size, num_heads, stream);
    else launch_typed<__nv_bfloat16, int32_t>(q_input, weight, static_cast<float>(weight_scale), freqs, positions, q_fp8, weights_out, batch_size, num_heads, stream);
  }
}

